  'media-viewer',
  'Media Viewer',
  'Responsive media components for images, galleries, and videos.',
  '1.0.0',
  'DocForge',
  '🖼️',
  '',
  'widget',
  1,
  '.df-media{margin:14px 0;color:var(--c-text)}.df-media-img{display:block;width:100%;max-width:100%;height:auto;border-radius:8px;object-fit:var(--df-fit,contain);background:var(--c-surface);border:1px solid var(--c-border)}.df-media-img.is-clickable,.content img.is-clickable{cursor:zoom-in}.df-media-caption{margin-top:7px;color:var(--c-muted);font-size:13px;line-height:1.5}.df-media-missing{display:flex;align-items:center;justify-content:center;min-height:160px;border:1.5px dashed var(--c-border);border-radius:8px;background:rgba(22,27,34,.35);color:var(--c-muted);font-family:var(--mono);font-size:12px}.df-gallery{display:grid;gap:10px}.df-gallery-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(var(--df-min,220px),1fr));gap:10px}.df-gallery-scroll{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:8px}.df-gallery-scroll .df-gallery-item{flex:0 0 min(78vw,var(--df-item,420px));scroll-snap-align:start}.df-gallery-item img{width:100%;aspect-ratio:var(--df-ratio,16/10);object-fit:var(--df-fit,cover)}.df-video{width:100%;max-width:100%;border-radius:8px;background:#000;border:1px solid var(--c-border);display:block}.df-media-lightbox{position:fixed;inset:0;z-index:9200;background:rgba(0,0,0,.88);display:none;align-items:center;justify-content:center;padding:28px;cursor:zoom-out}.df-media-lightbox.open{display:flex}.df-media-lightbox img,.df-media-lightbox video{max-width:94vw;max-height:90vh;object-fit:contain;border-radius:8px;box-shadow:0 18px 60px rgba(0,0,0,.55)}.df-media-close{position:absolute;right:18px;top:16px;width:36px;height:36px;border:1px solid rgba(255,255,255,.2);border-radius:999px;background:rgba(255,255,255,.12);color:#fff;font-size:20px;cursor:pointer}@media(max-width:720px){.df-gallery-grid{grid-template-columns:1fr}.df-gallery-scroll .df-gallery-item{flex-basis:86vw}}',
  '(function(){function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c];});}function mediaUrl(key){return (window.DocForge&&DocForge.media(key))||"";}function attr(el,n,d){var v=el.getAttribute(n);return v==null?d:v;}function bool(el,n,d){var v=el.getAttribute(n);if(v==null)return d;return !/^(0|false|no|off)$/i.test(v);}function missing(key,type){return "<div class=\"df-media-missing\">"+esc(type+": "+key)+"</div>";}function caption(el){var c=attr(el,"caption","");return c?"<figcaption class=\"df-media-caption\">"+esc(c)+"</figcaption>":"";}function renderImage(el){var key=attr(el,"key","")||attr(el,"src","");var src=mediaUrl(key)||key;if(!src)return missing(key,"image");var alt=attr(el,"alt","");var fit=attr(el,"fit","contain");var cap=caption(el);var light=bool(el,"lightbox",true);var cls="df-media-img"+(light?" is-clickable":"");return "<figure class=\"df-media\" style=\"--df-fit:"+esc(fit)+"\"><img class=\""+cls+"\" src=\""+esc(src)+"\" alt=\""+esc(alt)+"\" loading=\"lazy\" data-df-lightbox=\""+(light?"image":"")+"\">"+cap+"</figure>";}function renderVideo(el){var key=attr(el,"key","")||attr(el,"src","");var src=mediaUrl(key)||key;if(!src)return missing(key,"video");var poster=attr(el,"poster","");var posterUrl=poster?(mediaUrl(poster)||poster):"";var attrs=[bool(el,"controls",true)?"controls":"",bool(el,"autoplay",false)?"autoplay muted playsinline":"",bool(el,"loop",false)?"loop":"",posterUrl?"poster=\""+esc(posterUrl)+"\"":""].filter(Boolean).join(" ");var cap=caption(el);return "<figure class=\"df-media\"><video class=\"df-video\" src=\""+esc(src)+"\" "+attrs+"></video>"+cap+"</figure>";}function renderGallery(el){var keys=(attr(el,"keys","")||attr(el,"key","")).split(/[,\s]+/).map(function(k){return k.trim();}).filter(Boolean);if(!keys.length)return missing("","gallery");var mode=attr(el,"mode",attr(el,"layout","grid"));var fit=attr(el,"fit","cover");var ratio=attr(el,"ratio","16/10");var min=attr(el,"min","220px");var light=bool(el,"lightbox",true);var cls=mode==="scroll"?"df-gallery-scroll":"df-gallery-grid";var items=keys.map(function(key){var src=mediaUrl(key)||key;return "<div class=\"df-gallery-item\"><img class=\"df-media-img"+(light?" is-clickable":"")+"\" src=\""+esc(src)+"\" alt=\"\" loading=\"lazy\" data-df-lightbox=\""+(light?"image":"")+"\"></div>";}).join("");return "<figure class=\"df-media df-gallery\" style=\"--df-fit:"+esc(fit)+";--df-ratio:"+esc(ratio)+";--df-min:"+esc(min)+"\"><div class=\""+cls+"\">"+items+"</div>"+caption(el)+"</figure>";}function ensureBox(){var box=document.querySelector(".df-media-lightbox");if(box)return box;box=document.createElement("div");box.className="df-media-lightbox";box.innerHTML="<button class=\"df-media-close\" type=\"button\" aria-label=\"Close\">×</button><div class=\"df-media-stage\"></div>";document.body.appendChild(box);box.addEventListener("click",function(e){if(e.target===box||e.target.classList.contains("df-media-close"))closeBox();});document.addEventListener("keydown",function(e){if(e.key==="Escape")closeBox();});return box;}function closeBox(){var box=document.querySelector(".df-media-lightbox");if(!box)return;var v=box.querySelector("video");if(v){v.pause();v.removeAttribute("src");}box.classList.remove("open");box.querySelector(".df-media-stage").innerHTML="";}function setupLightbox(){document.querySelectorAll(".content img:not([data-df-no-lightbox]),[data-df-lightbox=\"image\"]").forEach(function(img){if(img.dataset.dfReady)return;img.dataset.dfReady="1";img.dataset.dfLightbox=img.dataset.dfLightbox||"image";img.classList.add("is-clickable");img.addEventListener("click",function(){var box=ensureBox();box.querySelector(".df-media-stage").innerHTML="<img src=\""+esc(img.currentSrc||img.src)+"\" alt=\""+esc(img.alt||"")+"\">";box.classList.add("open");});});}DocForge.register({id:"media-viewer",tagSchema:{"media-image":{description:"Render one image by media key or URL.",attrs:["key","src","alt","caption","fit","lightbox"]},"media-video":{description:"Render one video by media key or URL.",attrs:["key","src","poster","caption","controls","autoplay","loop"]},"media-gallery":{description:"Render multiple images by media keys or URLs.",attrs:["keys","mode","fit","ratio","min","caption","lightbox"]}},renderTags:{"media-image":renderImage,"media-video":renderVideo,"media-gallery":renderGallery},onLoad:setupLightbox});})();',
